import { useEffect, useState } from '@wordpress/element';
import { dispatch } from '@wordpress/data';
import { Panel, PanelBody, PanelRow, Notice } from '@wordpress/components';

import CampusDirectoryDepartmentDropdown from '../components//CampusDirectory/CampusDirectoryDepartmentDropdown';
import DivisionDropdown from '../components/DivisionDropdown';
import PageLayout from '../components/CampusDirectory/PageLayout';
import PeopleAndInformation from '../components/CampusDirectory/PeopleAndInformation';

const CampusDirectory = () => {
  wp.blocks.registerBlockType("ucscblocks/campusdirectory", {
    title: "Campus Directory",
    icon: "welcome-learn-more",
    category: "common",
    attributes: {
      pageLayout: { type: "string" },
      automatedFeeds: { type: "boolean" },
      cruzidList: { type: "string" },
      strFacultyTypes: { type: "string" },
      strStaffTypes: { type: "string" },
      strGradTypes: { type: "string" },
      manualAdd: { type: "boolean" },
      addCruzids: { type: "string" },
      excludeCruzids: { type: "string" },
      displayDeptartmentAffiliates: { type: "boolean" },
      linkToProfile: { type: "boolean" },
      linkOutToCampusDirectory: { type: "boolean" },
      strInformationTypes: { type: "string" },
      strInformationTypesTable: { type: "string" },
      department: { type: "string" },
      division: { type: "string" },
      deptOrDiv: { type: "string" },
    },
    edit: ({ setAttributes, attributes }) => {
      const {
        pageLayout,
        automatedFeeds,
        cruzidList,
        strFacultyTypes,
        strStaffTypes,
        strGradTypes,
        manualAdd,
        addCruzids,
        excludeCruzids,
        displayDeptartmentAffiliates,
        linkToProfile,
        linkOutToCampusDirectory,
        strInformationTypes,
        strInformationTypesTable,
        department,
        division,
        deptOrDiv,
      } = attributes;

      const [configuredCorrectly, setConfiguredCorrectly] = useState(true);
      const [resp, setResp] = useState({});
      const [isInvalidState, setIsInvalidState] = useState(false);

      // Lock or unlock post saving based on attribute state
      useEffect(() => {
        const invalidState = automatedFeeds && department === '---' && division === '---';
        setIsInvalidState(invalidState);

        if (invalidState) {
          dispatch('core/editor').lockPostSaving('campusDirectoryInvalidState');
        } else {
          dispatch('core/editor').unlockPostSaving('campusDirectoryInvalidState');
        }
      }, [automatedFeeds, department, division]);

      useEffect(() => {
        fetch("/wp-json/ucscgutenbergblocks/v1/campusdirectoryrequirements")
          .then((res) => res.text())
          .then((text) => {
            const resp = JSON.parse(text);
            if (!resp.ldap_pass) setConfiguredCorrectly(false);
            setResp(resp);
          });
      }, []);

      return (
        <>
          {isInvalidState && (
            <Notice
              status="error"
              isDismissible={false}
            >
              <strong>Unable to publish:</strong> Please select a valid department or division when using automated feeds to enable publishing.
            </Notice>
          )}
          {configuredCorrectly && (
            <Panel className="directory-block" header="Directory Block">
              <PanelBody title="Layout Type" initialOpen>
                <PanelRow>
                  <PageLayout
                    setAttributes={setAttributes}
                    pageLayout={pageLayout}
                  />
                </PanelRow>
              </PanelBody>
              <PanelBody title="People and Information to Display" initialOpen>
                <PanelRow>
                  <PeopleAndInformation
                    setAttributes={setAttributes}
                    automatedFeeds={automatedFeeds}
                    cruzidList={cruzidList}
                    strFacultyTypes={strFacultyTypes}
                    strStaffTypes={strStaffTypes}
                    strGradTypes={strGradTypes}
                    manualAdd={manualAdd}
                    addCruzids={addCruzids}
                    excludeCruzids={excludeCruzids}
                    displayDeptartmentAffiliates={displayDeptartmentAffiliates}
                    linkToProfile={linkToProfile}
                    linkOutToCampusDirectory={linkOutToCampusDirectory}
                    strInformationTypes={strInformationTypes}
                    strInformationTypesTable={strInformationTypesTable}
                    pageLayout={pageLayout}
                    division={division}
                    department={department}
                    deptOrDiv={deptOrDiv}
                  />
                </PanelRow>
              </PanelBody>
            </Panel>
          )}
          {!configuredCorrectly && (
            <>
              <h2>This Block is not Configured Correctly</h2>
              {!resp.ldap_pass && resp.multisite && (
                <>
                  <h4>
                    The LDAP password can be set at the network level{" "}
                    <a
                      target="_blank"
                      href="/wp-admin/network/settings.php?page=ucsc-gutenberg-blocks-network-settings"
                    >
                      here.
                    </a>
                  </h4>
                  <h6>
                    Or the LDAP password can be set at the site level below.
                  </h6>
                </>
              )}
              {!resp.ldap_pass && (
                <h4>
                  The LDAP password needs to be set here{" "}
                  <a
                    target="_blank"
                    href="/wp-admin/options-general.php?page=ucsc_gutenberg_blocks_settings_page"
                  >
                    here.
                  </a>
                </h4>
              )}
            </>
          )}
        </>
      );
    },
    save: () => {
      return null;
    },
  });
};

export default CampusDirectory;

import { Panel, PanelBody, RadioControl } from '@wordpress/components';

import DepartmentDropdown from '../components/DepartmentDropdown';
import SubjectDropdown from '../components/SubjectDropdown';


import { useState } from '@wordpress/element';



const ClassSchedule = () => {
  wp.blocks.registerBlockType("ucscblocks/classschedule", {
    title: "Class Schedule",
    icon: "schedule",
    category: "common",
    attributes: {
      subjectOrDept: {
        type: "string"
      },
      department: {
        type: "string"
      },
      subject: {
        type: "string"
      },
    },
    edit: ({ setAttributes, attributes }) => {
      const {
        department,
        subject,
        subjectOrDept,
      } = attributes;

      let localSubjectOrDept;
      let setLocalSubjectOrDept;
      if (typeof subjectOrDept === 'undefined') {
        [localSubjectOrDept, setLocalSubjectOrDept] = useState("dept");
        setAttributes({
          subjectOrDept: "dept",
        });
      } else {
        [localSubjectOrDept, setLocalSubjectOrDept] = useState(subjectOrDept);
      }

      const isDevEnvironment = () => {
        const isDevEnv = window.location.href.includes('https://wordpress-dev.ucsc.edu/')
                    || window.location.href.includes('wp-dev.ucsc');
        return isDevEnv;
      }

      const options = [
        { label: 'Department', value: 'dept' },
        { label: 'Subject', value: 'subject' },
      ];

      return (
        <>
          <Panel header="Class Schedule Block">
            <PanelBody title="Set Department or Subject" initialOpen>
              <div className="vertical_radio">
                <RadioControl
                  selected={localSubjectOrDept}
                  onChange={newLocalSubjectOrDept => {
                    setLocalSubjectOrDept(newLocalSubjectOrDept);
                    setAttributes({
                      subjectOrDept: newLocalSubjectOrDept,
                    });
                  }}
                  options={options}
                />
              </div>
              <hr />
              <DepartmentDropdown
                label="Departments"
                department={department}
                setAttributes={setAttributes}
                disabled={subjectOrDept !== "dept"}
              />
              <SubjectDropdown
                label="Subjects"
                subject={subject}
                setAttributes={setAttributes}
                disabled={subjectOrDept !== "subject"}
              />
              <small style={{ display: 'block', marginTop: '3em', fontSize: '0.7em', color: '#666' }}>version 1.1.37</small>
            </PanelBody>
          </Panel>
        </>
      );
    },
    save: (props) => {
      return null;
    },
    deprecated: [
      // The useNewServer attribute was removed from the block in the class_schedule_2.0 branch. Without a 
      // deprecated entry, existing posts that saved this attribute will trigger a block validation error in 
      // the editor. A deprecation migration silently strips it.
      {
        attributes: {
          subjectOrDept: { type: "string" },
          department:    { type: "string" },
          subject:       { type: "string" },
          useNewServer:  { type: "boolean" },
        },
        migrate( attributes ) {
          const { useNewServer, ...rest } = attributes;
          return rest;
        },
        save: () => null,
      },
    ],
  })
}

export default ClassSchedule;

import { useEffect, useState } from '@wordpress/element'
import { SelectControl } from '@wordpress/components';

const TestDemoUCSC = () => {
  wp.blocks.registerBlockType("ucscblocks/contentsharer", {
    title: "Content Sharer",
    icon: "admin-site-alt3",
    category: "common",
    attributes: {
      siteid: {
        type: "string"
      },
      postType: {
        type: "string"
      }
    },
    edit: ({ setAttributes, attributes }) => {
      const { siteid, postType } = attributes;


      let selectedSite, setSelectedSite;
      if (typeof siteid === 'undefined') {
        setAttributes({
          siteid: 1
        });
        [selectedSite, setSelectedSite] = useState(1);
      } else {
        [selectedSite, setSelectedSite] = useState(siteid);
      }

      let selectedPostType, setSelectedPostType;
      if (typeof postType === 'undefined') {
        setAttributes({
          postType: ""
        });
        [selectedPostType, setSelectedPostType] = useState("");
      } else {
        [selectedPostType, setSelectedPostType] = useState(postType);
      }

      const [sites, setSites] = useState([]);
      const [postTypes, setPostTypes] = useState([]);

      const fetchPostTypes = (siteid) => {
        fetch('/wp-json/ucscgutenbergblocks/v1/posttypes?siteid=' + siteid)
          .then(res => res.text())
          .then((text) => {
            const postTypes = JSON.parse(text);
            const pTypes = [];
            Object.keys(postTypes).map(type => {
              pTypes.push({
                label: type,
                value: type
              })
            })
            setPostTypes(pTypes);
          })
      }

      useEffect(() => {
        fetch('/wp-json/ucscgutenbergblocks/v1/sites')
          .then(res => res.text())
          .then((text) => {
            setSites(JSON.parse(text));
          });
        fetchPostTypes(selectedSite);
      }, []);

      const options = sites.map(site => {
        return {
          label: site.domain,
          value: site.blog_id
        }
      })

      const userSelectedASite = (e) => {
        setSelectedSite(e.target.value);
        setAttributes({
          siteid: e.target.value
        });
        fetchPostTypes(e.target.value);
      }

      const userSelectedAPostType = (e) => {
        setSelectedPostType(e.target.value);
        setAttributes({
          postType: e.target.value
        });
      }

      return (
        <>
          <h2>Content Sharerer</h2>
          <h4>Site List</h4>
          <select
            value={selectedSite}
            onChange={userSelectedASite}
          >
            {options.map((option) => (
              <option value={option.value} >{option.label}</option>
            ))}
          </select>
          <h4>Post Types</h4>
          <select
            value={selectedPostType}
            onChange={userSelectedAPostType}
          >
            {postTypes.map((type) => (
              <option value={type.value} >{type.label}</option>
            ))}
          </select>
        </>
      );
    },
    save: (props) => {
      return null;
    }
  })
}

export default TestDemoUCSC;

